import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage, toQuery } from '@/lib/admin-client';

type Patient = { id: string; full_name?: string; phone?: string; email?: string; verified?: boolean; bookings_total?: number; createdAt?: string };
type Patients = { data: Patient[]; total: number; page: number; pages: number };
type Patient360 = { profile: Record<string, any>; bookings_by_kind: Array<{ kind: string; label_ar: string; count: number; rows: Array<Record<string, any>> }>; wallet: { balance: number; recent_transactions: Array<Record<string, any>> }; support_tickets: Array<Record<string, any>>; devices: Array<Record<string, any>>; financial_summary: { lifetime_paid: number; paid_orders: number } };

export default function CrmPage() {
  const [q, setQ] = useState(''); const [page, setPage] = useState(1); const [patients, setPatients] = useState<Patients>({ data: [], total: 0, page: 1, pages: 1 }); const [selected, setSelected] = useState<Patient360 | null>(null); const [selectedId, setSelectedId] = useState(''); const [loading, setLoading] = useState(true); const [detailLoading, setDetailLoading] = useState(false); const [error, setError] = useState(''); const [impersonationNotice, setImpersonationNotice] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { setPatients(await adminFetch<Patients>(`/crm/patients${toQuery({ q, page, limit: 25 })}`)); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل دليل العملاء.')); } finally { setLoading(false); } }, [q, page]);
  useEffect(() => { void load(); }, [load]);
  async function openPatient(id: string) { setSelectedId(id); setDetailLoading(true); setError(''); setImpersonationNotice(''); try { setSelected(await adminFetch<Patient360>(`/crm/patients/${encodeURIComponent(id)}/360`)); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل ملف CRM 360.')); } finally { setDetailLoading(false); } }
  async function requestImpersonation() { if (!selectedId || !window.confirm('سيتم إنشاء جلسة دعم قصيرة وتسجيلها في سجل التدقيق. لا تستخدمها إلا لغرض دعم مشروع. متابعة؟')) return; try { const result = await adminMutation<{ warning?: string; expires_at?: string }>('/impersonation/start', 'POST', { user_id: selectedId, minutes: 15, reason: 'دعم فني — CRM 360' }); setImpersonationNotice(`${result.warning || 'تم إنشاء جلسة الدعم عبر BFF.'} تنتهي في ${result.expires_at ? new Date(result.expires_at).toLocaleString('ar-SA') : '15 دقيقة'}.`); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إنشاء جلسة الدعم.')); } }
  return <><Head><title>CRM 360 | نبض</title></Head><section dir="rtl" className="p-6 md:p-8"><header className="mb-6"><h1 className="text-3xl font-bold">CRM 360</h1><p className="mt-1 text-sm text-slate-500">دليل العملاء وملف موحد من بيانات المستخدم والمحفظة والطلبات والتذاكر والأجهزة.</p></header>{error ? <p role="alert" className="mb-4 rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}{impersonationNotice ? <p role="status" className="mb-4 rounded-lg bg-amber-50 p-3 text-amber-800">{impersonationNotice}</p> : null}<div className="grid gap-6 lg:grid-cols-5"><aside className="lg:col-span-2"><div className="rounded-2xl border bg-white p-4 shadow-sm"><div className="flex gap-2"><input value={q} onChange={(e) => { setQ(e.target.value); setPage(1); }} className="w-full rounded-lg border px-3 py-2 text-sm" placeholder="اسم أو جوال أو بريد أو معرّف"/><button onClick={() => void load()} className="rounded-lg bg-teal-700 px-3 text-sm font-bold text-white">بحث</button></div><ul className="mt-4 divide-y">{loading ? <li className="p-6 text-center text-sm text-slate-500">جارٍ تحميل العملاء…</li> : patients.data.length ? patients.data.map((patient) => <li key={patient.id}><button onClick={() => void openPatient(patient.id)} className={`w-full p-4 text-right hover:bg-slate-50 ${selectedId === patient.id ? 'bg-teal-50' : ''}`}><strong>{patient.full_name || patient.id}</strong><span className="mt-1 block text-xs text-slate-500">{patient.phone || patient.email || '—'} · {patient.bookings_total ?? 0} طلب</span></button></li>) : <li className="p-6 text-center text-sm text-slate-500">لا توجد نتائج.</li>}</ul><div className="mt-4 flex justify-between text-sm"><button className="rounded border px-3 py-1 disabled:opacity-40" disabled={page <= 1} onClick={() => setPage((v) => v - 1)}>السابق</button><span>{patients.page} / {patients.pages || 1}</span><button className="rounded border px-3 py-1 disabled:opacity-40" disabled={page >= (patients.pages || 1)} onClick={() => setPage((v) => v + 1)}>التالي</button></div></div></aside><div className="lg:col-span-3">{detailLoading ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">جارٍ بناء ملف العميل…</p> : !selected ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">اختر عميلاً من الدليل لعرض ملف 360.</p> : <div className="space-y-5"><article className="rounded-2xl border bg-white p-6 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-bold">{selected.profile.full_name || selected.profile.id}</h2><p className="mt-1 text-sm text-slate-500">{selected.profile.phone || ''} {selected.profile.email ? `· ${selected.profile.email}` : ''}</p></div><button onClick={() => void requestImpersonation()} className="rounded-lg border border-amber-700 px-3 py-2 text-sm font-bold text-amber-800">تسجيل انتحال للدعم</button></div><div className="mt-4 grid gap-3 md:grid-cols-3"><div className="rounded bg-slate-50 p-3 text-sm">رصيد المحفظة<strong className="block text-lg">{selected.wallet.balance} ر.س</strong></div><div className="rounded bg-slate-50 p-3 text-sm">مدفوع مدى الحياة<strong className="block text-lg">{selected.financial_summary.lifetime_paid} ر.س</strong></div><div className="rounded bg-slate-50 p-3 text-sm">طلبات مدفوعة<strong className="block text-lg">{selected.financial_summary.paid_orders}</strong></div></div></article><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">الطلبات حسب العمودي</h2><div className="mt-4 grid gap-3 md:grid-cols-2">{selected.bookings_by_kind.map((group) => <div key={group.kind} className="rounded-lg border p-3"><h3 className="font-medium">{group.label_ar} <span className="text-slate-500">({group.count})</span></h3><ul className="mt-2 space-y-1 text-sm">{group.rows.map((row) => <li key={row.id} className="flex justify-between border-t pt-1"><span className="font-mono text-xs">{row.id}</span><span>{row.state || '—'} · {row.total ?? '—'} ر.س</span></li>)}</ul></div>)}</div></article><div className="grid gap-5 md:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">الأجهزة والجلسات</h2><ul className="mt-3 space-y-2 text-sm">{selected.devices.length ? selected.devices.map((device, index) => <li key={index} className="rounded bg-slate-50 p-2">{device.device_name || device.platform || 'جهاز غير مسمى'} · {device.last_seen_at ? new Date(device.last_seen_at).toLocaleString('ar-SA') : '—'} · {device.revoked ? 'مسحوبة' : 'نشطة'}</li>) : <li className="text-slate-500">لا توجد جلسات مسجلة.</li>}</ul></article><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">تذاكر الدعم</h2><ul className="mt-3 space-y-2 text-sm">{selected.support_tickets.length ? selected.support_tickets.map((ticket) => <li key={ticket.id} className="rounded bg-slate-50 p-2"><strong>{ticket.tracking_id || ticket.id}</strong> · {ticket.subject || ticket.category} · {ticket.status}</li>) : <li className="text-slate-500">لا توجد تذاكر.</li>}</ul></article></div></div>}</div></div></section></>;
}
